# Anti-diagonal reflection: (i,j) -> (n-1-j, n-1-i)
original = [
    [3, 0, 0],
    [3, 3, 3],
    [0, 0, 3]
]

n = 3
reflected = [[0]*n for _ in range(n)]
for i in range(n):
    for j in range(n):
        if original[i][j] == 3:
            reflected[n-1-j][n-1-i] = 3

print("Anti-diagonal reflection:")
for row in reflected:
    print(row)

# Exact complement (swap 0 and 3)
original = [
    [3, 0, 0],
    [3, 3, 3],
    [0, 0, 3]
]

complement = []
for row in original:
    new_row = []
    for cell in row:
        if cell == 3:
            new_row.append(0)
        elif cell == 0:
            new_row.append(3)
    complement.append(new_row)

print("Exact complement:")
for row in complement:
    print(row)

action = '{"action": "submit", "grid": ' + str(complement) + '}'
print(action)

